func TestHoldJournalDeduplicatesReasons(t *testing.T) {
	journal := installTestJournal(t)
	holds := newHoldJournal("lab")
	now := time.Now()
	reason := "member m1 OCI host is not currently observed; retained volume creation is withheld"
