		`"nats":{"embedded":{"interregion":{"enabled":` + value + `}}}`,
	} {
		if _, err := decodeConfig([]byte(`{"version":2,` + block + `}`)); err == nil {
			t.Fatalf("removed field accepted: %s", block)
		}
	}
}

