func startRuntimeObservability(ctx context.Context, cfg Config, role, member string) (*runtimeObservability, error) {
	settings := cfg.Observability
	if err := settings.Validate(); err != nil {
		return nil, err
	}
	runtime := &runtimeObservability{config: settings, cell: cfg.NATS.Cell, member: member, role: role,
		operationObservations: &operationObservationAPI{cell: cfg.NATS.Cell},
		registry:              observability.NewRegistry(true), health: new(observability.Health),
		events: observability.NewEventBus(observability.DefaultEventCapacity)}
	logger, err := observability.NewLogger(os.Stderr,
		observability.LogConfig{Format: settings.LogFormat, Level: settings.LogLevel}, runtime.events,
		observability.Identity(role, cfg.NATS.Cell)...)
	if err != nil {
		return nil, err
	}
	observability.ConfigureDefault(logger)
	runtime.registry.Register(observability.LogMetrics)
	runtime.health.Add(observability.Check{Name: "startup", Run: func(context.Context) (bool, string) {
		if runtime.started.Load() {
			return true, "runtime started"
		}
		return false, "runtime is still starting"
	}})
	if role == "controller" {
		runtime.usage = capacity.NewStore(cfg.NATS.Cell)
		runtime.startDecisionJournal(ctx)
	}
	server, err := observability.NewServer(settings, observability.ServerDeps{Registry: runtime.registry,
		Health: runtime.health, Events: runtime.events, LocalSessions: role == "host"})
	if err != nil {
		// An unusable bearer token file (missing, shared or malformed) fails
		// closed for the listener only: nothing is served, and the role
		// keeps running exactly as when the port cannot be bound.
		slog.WarnContext(ctx, "observability listener unusable; continuing without it",
			observability.ComponentKey, "observability", "error", err)
		return runtime, nil
	}
	runtime.mountUsage(server)
	runtime.operationObservations.mount(server)
	// A token-protected listener issues browser sessions; a tokenless
	// one is loopback only and refuses DNS names against rebinding.
	board := dashboard.New(dashboard.Options{Health: runtime.health, Events: runtime.events,
		SignOut: settings.BearerTokenFile != "", RequireLiteralHost: settings.BearerTokenFile == ""})
	board.Mount(server)
	serveErrors, err := server.Start(ctx, settings)
	if err != nil {
		slog.WarnContext(ctx, "observability listener unavailable; continuing without it",
			observability.ComponentKey, "observability", "address", settings.Address(), "error", err)
		return runtime, nil
	}
	go watchObservabilityListener(serveErrors)
	runtime.server = server
	runtime.addBoard(board, server)
	slog.InfoContext(ctx, "observability listener ready", observability.ComponentKey, "observability",
		"address", server.Addr().String())
	return runtime, nil
}

func controllerCredentialFiles(cfg Config) []maintenance.CredentialFile {
	files := tlsFiles("nats client", cfg.NATS.TLS)
	files = append(files, maintenance.CredentialFile{Name: "nats client credentials", Path: cfg.NATS.CredentialsFile})
	if embedded := cfg.NATS.Embedded; embedded != nil {
		files = append(files, tlsFiles("nats server", embedded.TLS)...)
		files = append(files, tlsFiles("nats route", embedded.RouteTLS)...)
		files = append(files,
			maintenance.CredentialFile{Name: "nats operator jwt", Path: embedded.OperatorJWTFile},
			maintenance.CredentialFile{Name: "nats system account jwt", Path: embedded.SystemJWTFile},
			maintenance.CredentialFile{Name: "nats cell account jwt", Path: embedded.CellJWTFile},
			maintenance.CredentialFile{Name: "nats system credentials", Path: embedded.SystemCredentialsFile},
			maintenance.CredentialFile{Name: "nats membership credentials", Path: embedded.MembershipCredentialsFile})
		if link := embedded.InterRegion; link != nil {
			files = append(files, maintenance.CredentialFile{Name: "interregion account jwt", Path: link.AccountJWTFile})
			if link.Listen != nil {
				files = append(files, tlsFiles("interregion listen", link.Listen.TLS)...)
			}
			for _, remote := range link.Remotes {
				files = append(files, tlsFiles("interregion "+remote.Peer, remote.TLS)...)
				files = append(files, maintenance.CredentialFile{Name: "interregion " + remote.Peer + " credentials",
					Path: remote.CredentialsFile})
			}
		}
		if link := embedded.Link; link != nil {
			files = append(files, tlsFiles("region link", link.TLS)...)
			if link.CredentialsFile != "" {
				files = append(files, maintenance.CredentialFile{Name: "region link credentials", Path: link.CredentialsFile})
			}
		}
	}
	return append(files,
		maintenance.CredentialFile{Name: "host tls issuer", Path: cfg.Controller.HostTLSIssuerCertFile},
		maintenance.CredentialFile{Name: "terrabase member ca", Path: cfg.Controller.TerraBaseCACertFile})
}

func tlsFiles(name string, files natscell.TLSFiles) []maintenance.CredentialFile {
	return []maintenance.CredentialFile{{Name: name + " tls", Path: files.CertFile}, {Name: name + " ca", Path: files.CAFile}}
}

func newAuthenticatedNATS(t *testing.T, cell string, brokers ...string) *authenticatedNATS {
	t.Helper()
	a := &authenticatedNATS{root: t.TempDir(), cell: cell, brokers: slices.Clone(brokers)}
	a.tls, a.routePassword = testR3TLSMaterial(t, a.root)
	operator, err := nkeys.CreateOperator()
	if err != nil {
		t.Fatal(err)
	}
	system, err := nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	a.account, err = nkeys.CreateAccount()
	if err != nil {
		t.Fatal(err)
	}
	operatorID, _ := operator.PublicKey()
	systemID, _ := system.PublicKey()
	a.cellID, _ = a.account.PublicKey()
	operatorClaim := jwt.NewOperatorClaims(operatorID)
	operatorClaim.SystemAccount = systemID
	operatorJWT, err := operatorClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	systemJWT, err := jwt.NewAccountClaims(systemID).Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	cellClaim := jwt.NewAccountClaims(a.cellID)
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: 256 << 20, DiskStorage: 8 << 30, Streams: 100, Consumer: 100}
	a.cellJWT, err = cellClaim.Encode(operator)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name, raw string) string {
		path := filepath.Join(a.root, name)
		if err := os.WriteFile(path, []byte(raw), 0o600); err != nil {
			t.Fatal(err)
		}
		return path
	}
	a.operatorFile = write("operator.jwt", operatorJWT)
	a.systemFile = write("system.jwt", systemJWT)
	a.cellFile = write("cell.jwt", a.cellJWT)
	systemUser, systemCredentials := testBrokerJWTUser(t, a.root, "system.creds", system, systemID,
		[]string{"$SYS.REQ.ACCOUNT." + a.cellID + ".CLAIMS.UPDATE"}, nil)
	systemClaim, err := jwt.DecodeUserClaims(testDecoratedJWT(t, systemCredentials))
	if err != nil {
		t.Fatal(err)
	}
	systemClaim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(cell, systemUser) + ".>"}
	a.systemCredentials = testBrokerJWTUserWithClaim(t, a.root, "system.creds", system, systemClaim)
	public, _ := testEd25519(t, a.root, "ticket.key")
	a.ticketPrivateFile = filepath.Join(a.root, "ticket.key")
	a.ticketPublicFile = write("ticket.pub", base64.StdEncoding.EncodeToString(public))
	return a
}

func (a *authenticatedNATS) config(t *testing.T, cfg natscell.Config) natscell.Config {
	t.Helper()
	if cfg.Cell != "" && cfg.Cell != a.cell {
		t.Fatalf("fixture cell %q differs from client cell %q", a.cell, cfg.Cell)
	}
	cfg.Cell = a.cell
	if cfg.Instance == "" {
		cfg.Instance = "one"
	}
	if cfg.Replicas == 0 {
		cfg.Replicas = 1
	}
	role := cfg.ClientRole
	if role == "" {
		role = "controller"
	}
	var user nkeys.KeyPair
	var err error
	if cfg.NKeySeedFile != "" {
		seed, readErr := os.ReadFile(cfg.NKeySeedFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.FromSeed(seed)
		clear(seed)
	} else if cfg.CredentialsFile != "" {
		credentials, readErr := os.ReadFile(cfg.CredentialsFile)
		if readErr != nil {
			t.Fatal(readErr)
		}
		user, err = nkeys.ParseDecoratedUserNKey(credentials)
		clear(credentials)
	} else {
		user, err = nkeys.CreateUser()
	}
	if err != nil {
		t.Fatal(err)
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		t.Fatal(err)
	}
	claim := jwt.NewUserClaims(public)
	claim.IssuerAccount = a.cellID
	claim.Sub.Allow = jwt.StringList{protocol.InboxPrefix(a.cell, public) + ".>"}
	switch role {
	case "controller":
		claim.Pub.Allow = natscell.ControllerPublishes(a.cell)
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Pub.Allow.Add("$JS.ACK.>")
		claim.Sub.Allow.Add(natscell.ControllerSubscriptions(a.cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(a.cell), protocol.Broker(a.cell, "ticket", ">"), protocol.Broker(a.cell, "fence", cfg.Instance))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
	case "operator":
		claim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(a.cell)
	case "host":
		claim.Pub.Allow = jwt.StringList{protocol.AgentObservation(a.cell, public, "*")}
	default:
		t.Fatalf("unsupported authenticated fixture role %q", role)
	}
	cfg.CredentialsFile = testBrokerJWTUserWithKey(t, a.root, cfg.Instance+"-"+public+".creds", a.account, user, claim)
	cfg.NKeySeedFile = ""
	cfg.TLS = a.tls
	cfg.URL = strings.ReplaceAll(cfg.URL, "nats://", "tls://")
	if cfg.Embedded != nil {
		embedded := *cfg.Embedded
		cfg.Embedded = &embedded
		embedded.Users = nil
		embedded.TLS, embedded.RouteTLS = a.tls, a.tls
		embedded.RouteUser, embedded.RoutePasswordFile = "integration-route", a.routePassword
		embedded.OperatorJWTFile, embedded.SystemJWTFile, embedded.CellJWTFile = a.operatorFile, a.systemFile, a.cellFile
		embedded.SystemCredentialsFile, embedded.TicketPublicKeyFile = a.systemCredentials, a.ticketPublicFile
		embedded.BrokerIDs = slices.Clone(a.brokers)
		if len(embedded.BrokerIDs) == 0 {
			embedded.BrokerIDs = []string{cfg.Instance}
		}
		if embedded.StoreDir == "" {
			embedded.StoreDir = filepath.Join(a.root, cfg.Instance)
		}
		if embedded.Host == "" {
			embedded.Host = "127.0.0.1"
		}
		if embedded.Port == 0 {
			embedded.Port = reserveControllerPort(t)
		}
	}
	return cfg
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

func (runtime *runtimeObservability) dashboardLoop(ctx context.Context, current func() (*cellspec.Dashboard, uint64),
	addresses func() (netbirdAddresses, bool), readToken func(context.Context, vaultsecret.Ref) (vaultsecret.VersionedValue, error),
) {
	var running, want dashboardListener
	var serving <-chan error
	var read time.Time
	stop, failure := func() {}, ""
	defer func() { stop() }()
	ticker := time.NewTicker(dashboardCheck)
	defer ticker.Stop()
	for {
		ctx := observability.StartTrace(ctx)
		section, generation := current()
		var err error
		if section == nil {
			want = dashboardListener{}
		} else if want.section != *section || want.generation != generation || time.Since(read) >= dashboardTokenRead {
			token, readErr := readToken(ctx, section.Token)
			switch {
			case readErr == nil:
				want.generation = generation
				want.section, want.token, read = *section, token, time.Now()
			case want.section != *section:
				// A new section never serves the old token.
				want, read, err = dashboardListener{section: *section}, time.Time{}, readErr
			default:
				// Vault is unavailable: keep serving the token read last.
				err = readErr
			}
		}
		if section != nil && err == nil {
			var found bool
			if want.addresses, found = addresses(); !found {
				err = errNoNetBirdAddress
			}
		}
		if want != running || serving == nil && section != nil && err == nil {
			stop()
			stop, running, serving = func() {}, dashboardListener{}, nil
			if section != nil && err == nil {
				stop, serving, err = runtime.startDashboard(ctx, want)
				if err != nil {
					// A cached version rejected by KV must be refreshed next check.
					read = time.Time{}
				}
				if err == nil {
					running = want
					slog.InfoContext(ctx, "dashboard serving on the NetBird address", observability.ComponentKey, "dashboard",
						"addresses", want.addresses.listen())
				}
			}
		}
		if err != nil && err.Error() != failure {
			slog.WarnContext(ctx, "dashboard is not serving on the NetBird address; retrying", observability.ComponentKey, "dashboard",
				"error", err)
		}
		failure = ""
		if err != nil {
			failure = err.Error()
		}
		select {
		case <-ctx.Done():
			return
		case err := <-serving:
			slog.WarnContext(ctx, "dashboard NetBird listener stopped; restarting", observability.ComponentKey, "dashboard", "error", err)
			stop()
			stop, running, serving = func() {}, dashboardListener{}, nil
		case <-ticker.C:
		}
	}
}

func (runtime *runtimeObservability) startDashboard(ctx context.Context, listener dashboardListener) (func(), <-chan error, error) {
	openCtx, openCancel := context.WithTimeout(ctx, 5*time.Second)
	store, err := observability.OpenSessionStore(openCtx, runtime.sessionJS, runtime.sessionReplicas, "netbird")
	openCancel()
	if err != nil {
		return func() {}, nil, err
	}
	serveCtx, cancel := context.WithCancel(ctx)
	var servers []*observability.Server
	var boards []*dashboard.Dashboard
	stop := func() {
		cancel()
		for _, server := range servers {
			_ = server.Close()
		}
		for _, board := range boards {
			runtime.removeBoard(board)
		}
	}
	stopped := make(chan error, len(listener.addresses))
	for _, address := range listener.addresses.listen() {
		settings := observability.Config{ListenAddress: address}
		server, err := observability.NewTokenServer(settings, listener.token.Value, observability.ServerDeps{
			Registry: runtime.registry, Health: runtime.health, Events: runtime.events, Sessions: store,
			TokenVersion: observability.TokenVersion{Source: listener.token.SecretID, Number: listener.token.Number, SpecGeneration: listener.generation}})
		if err != nil {
			stop()
			return func() {}, nil, err
		}
		board := dashboard.New(dashboard.Options{Health: runtime.health, Events: runtime.events, SignOut: true})
		runtime.mountUsage(server)
		if runtime.operationObservations != nil {
			runtime.operationObservations.mount(server)
		}
		runtime.boardsMu.Lock()
		if runtime.snapshots != nil {
			server.HandleSnapshots(runtime.snapshots)
		}
		if runtime.cluster != nil {
			server.HandleCluster(runtime.cluster)
		}
		if providers := runtime.providers.Load(); providers != nil {
			mountJournalAPI(server, *providers)
		}
		runtime.boardsMu.Unlock()
		board.Mount(server)
		serving, err := server.Start(serveCtx, settings)
		if err != nil {
			stop()
			return func() {}, nil, err
		}
		servers, boards = append(servers, server), append(boards, board)
		runtime.addBoard(board, server)
		go func() { stopped <- <-serving }()
	}
	return stop, stopped, nil
}

func OpenSessionStore(ctx context.Context, js jetstream.JetStream, replicas int, scope string) (*SessionStore, error) {
	if js == nil || replicas < 1 || replicas > 5 || scope == "" {
		return nil, errors.New("dashboard sessions require JetStream, replicas and a listener scope")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: SessionBucket, Description: "Hashed dashboard sessions and token generations",
		History: 1, Storage: jetstream.FileStorage, Replicas: replicas,
		MaxValueSize: 1024, MaxBytes: 16 << 20,
	})
	if err != nil {
		return nil, err
	}
	leader, err := js.Conn().JetStream()
	if err != nil {
		return nil, err
	}
	stream, err := js.Stream(ctx, "KV_"+SessionBucket)
	if err != nil {
		return nil, err
	}
	return &SessionStore{kv: kv, leader: leader, scope: sessionHash(scope), stream: stream}, nil
}

func (server *Server) Start(ctx context.Context, config Config) (<-chan error, error) {
	address, err := ValidateListenAddress(config.Address())
	if err != nil {
		return nil, err
	}
	// The token was read by NewServer from its own config; never let a
	// different Start config widen a tokenless server onto a network address.
	if !address.Addr().IsLoopback() && server.token == nil {
		return nil, errors.New("a non-loopback observability listener requires bearer_token_file")
	}
	var tlsConfig *tls.Config
	if config.TLSCertFile != "" {
		certificate, err := tls.LoadX509KeyPair(config.TLSCertFile, config.TLSKeyFile)
		if err != nil {
			return nil, fmt.Errorf("load observability TLS: %w", err)
		}
		tlsConfig = &tls.Config{MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{certificate}}
	}
	listener, err := (&net.ListenConfig{}).Listen(ctx, "tcp", address.String())
	if err != nil {
		return nil, err
	}
	if tlsConfig != nil {
		listener = tls.NewListener(listener, tlsConfig)
	}
	// No WriteTimeout: dashboard streams are long-lived. Headers and request
	// bodies are bounded as for the host enrollment listener.
	server.http = &http.Server{Handler: TraceHTTP(server), ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout: 10 * time.Second, IdleTimeout: time.Minute, MaxHeaderBytes: 4096}
	server.listen = listener
	if server.token != nil {
		cleanupCtx, cancel := context.WithCancel(ctx)
		server.reclaimCancel, server.reclaimDone = cancel, make(chan struct{})
		go func() {
			defer close(server.reclaimDone)
			server.sessions.retryCleanup(cleanupCtx)
		}()
	}
	result := make(chan error, 1)
	go func() {
		err := server.http.Serve(listener)
		if errors.Is(err, http.ErrServerClosed) {
			err = nil
		}
		result <- err
	}()
	context.AfterFunc(ctx, func() { _ = server.Close() })
	return result, nil
}

func (runtime *runtimeObservability) attachController(ctx context.Context, observed controllerObservation,
	filesystems []observability.FilesystemRole,
) error {
	runtime.sessionJS, runtime.sessionReplicas = observed.nats.JetStream(), observed.replicas
	runtime.attachLogs(ctx, observed)
	if runtime.server != nil && runtime.config.BearerTokenFile != "" {
		go retryAttachment(ctx, "dashboard", "dashboard session storage", func(attempt context.Context) error {
			store, err := observability.OpenSessionStore(attempt, runtime.sessionJS, runtime.sessionReplicas, "local."+runtime.member)
			if err != nil {
				return err
			}
			return runtime.server.SetSessionStore(attempt, store)
		})
	}
	runtime.registry.Register(delivery.Metrics)
	runtime.registry.Register(oci.Metrics)
	runtime.registry.Register(placement.Metrics)
	runtime.health.Add(observability.Check{Name: "nats", Run: func(context.Context) (bool, string) {
		if observed.nats.Ready() {
			return true, "regional broker connected"
		}
		return false, "regional broker is not connected"
	}})
	runtime.health.Add(observability.Check{Name: "cluster", Run: func(context.Context) (bool, string) {
		if observed.nats.FullClusterReady(observed.replicas) {
			return true, fmt.Sprintf("%d of %d replicas routed", observed.replicas, observed.replicas)
		}
		return false, "regional cluster is below its full replica count"
	}})
	runtime.health.Add(observability.Check{Name: "authority", Run: func(context.Context) (bool, string) {
		if lease := observed.authority.Current(); lease.Ready {
			if lease.Leader {
				return true, fmt.Sprintf("this controller holds the lease, epoch %d", lease.Epoch)
			}
			return true, fmt.Sprintf("lease observed, epoch %d", lease.Epoch)
		}
		return false, "authority lease is not observed"
	}})
	config := observability.CollectorConfig{Cell: runtime.cell, Member: runtime.member, Role: runtime.role,
		Registry: runtime.registry, Health: runtime.health, Filesystems: filesystems,
		Authority:   func() observability.AuthorityView { return authorityView(observed.authority.Current()) },
		NATS:        observed.nats.Observe,
		Delivery:    delivery.View,
		KVSnapshots: observed.kvSnapshots,
		OCI:         oci.APIView,
	}
	config.Links = func() []observability.RegionLinkProbe {
		if observed.linkProbes == nil {
			return nil
		}
		probes := observed.linkProbes()
		links := make([]observability.RegionLinkProbe, len(probes))
		for index, probe := range probes {
			links[index] = observability.RegionLinkProbe{Region: probe.Region, ObservedAt: probe.ObservedAt,
				Reach: probe.Reach, WAN: probe.WAN, LagGroups: probe.Lag, RTTMillis: probe.RoundTripMS}
		}
		return links
	}
	if observed.placements != nil {
		store := observed.placements
		config.Placement = func(ctx context.Context) (observability.PlacementView, error) {
			return placement.Summarize(ctx, store)
		}
	}
	if files := observed.credentials; len(files) > 0 {
		var mu sync.Mutex
		var last string
		config.Credentials = func() ([]observability.CredentialView, error) {
			credentials, err := maintenance.Scan(files)
			// The snapshot carries only an error class; log which file
			// failed, once per change. Roles and paths are not secret.
			text := ""
			if err != nil {
				text = err.Error()
			}
			mu.Lock()
			if text != "" && text != last {
				slog.WarnContext(ctx, "credential expiry scan incomplete", observability.ComponentKey, "maintenance", "error", err)
			}
			last = text
			mu.Unlock()
			return credentials, err
		}
	}
	collector, err := observability.NewCollector(config)
	if err != nil {
		return err
	}
	runtime.attachSnapshots(collector)
	// Cell-wide aggregation is telemetry too: a subscription the broker
	// refuses (for example credentials without the obs grant) leaves this
	// member's own view in place instead of stopping the controller.
	if _, err := observability.ServeSnapshots(ctx, observed.nats.Conn(), runtime.cell, collector); err != nil {
		slog.WarnContext(ctx, "cell-wide observability unavailable; serving the local view only",
			observability.ComponentKey, "observability", "error", err)
		runtime.attachJournal(ctx, observed, collector, nil)
		return nil
	}
	aggregator, err := observability.NewAggregator(observed.nats.Conn(), runtime.cell, observed.brokerIDs,
		observability.DefaultAggregationTimeout)
	if err != nil {
		slog.WarnContext(ctx, "cell-wide observability unavailable; serving the local view only",
			observability.ComponentKey, "observability", "error", err)
		runtime.attachJournal(ctx, observed, collector, nil)
		return nil
	}
	if runtime.server != nil {
		runtime.server.HandleCluster(aggregator)
	}
	runtime.attachBoards(func() { runtime.cluster = aggregator })
	runtime.attachJournal(ctx, observed, collector, aggregator)
	return nil
}

func (runtime *runtimeObservability) removeBoard(board *dashboard.Dashboard) {
	runtime.boardsMu.Lock()
	defer runtime.boardsMu.Unlock()
	delete(runtime.boards, board)
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
