func waitForDecisions(t *testing.T, journal *decisionlog.Journal, kind decisionlog.Kind, count int) []decisionlog.Decision {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for {
		result, _ := journal.Query(t.Context(), decisionlog.Query{Kinds: []decisionlog.Kind{kind}})
		if len(result.Decisions) >= count {
			return result.Decisions
		}
		if time.Now().After(deadline) {
			t.Fatalf("want %d %s decisions, have %d", count, kind, len(result.Decisions))
		}
		time.Sleep(20 * time.Millisecond)
	}
}

func watchControlPlane(ctx context.Context, cell, member string, fencer authority.Fencer, nats clusterHealth,
	replicas int,
) {
	if fencer == nil || nats == nil {
		return
	}
	healthEvery := clusterHealthInterval
	ticker := time.NewTicker(controlPlaneWatchInterval)
	defer ticker.Stop()
	var observedEpoch uint64
	wasLeader, wasMetaLeader := false, false
	metaLeader := ""
	healthy, everHealthy := false, false
	var lastHealthCheck time.Time
	for {
		ctx := observability.StartTrace(ctx)
		snapshot := fencer.Current()
		leading := snapshot.Leader && snapshot.Ready
		if leading && (!wasLeader || snapshot.Epoch != observedEpoch) {
			recordLeadership(ctx, cell, member, snapshot, observedEpoch)
		}
		wasLeader = leading
		if snapshot.Epoch > 0 {
			observedEpoch = snapshot.Epoch
		}
		if time.Since(lastHealthCheck) >= healthEvery {
			lastHealthCheck = time.Now()
			ready := nats.FullClusterReady(replicas)
			// The first full formation at startup is not a recovery. A
			// follower records it too when it observes no valid lease: the
			// authority runtime keeps its own candidate as OwnerID on
			// control-log failures, so an empty OwnerID is not the test.
			//
			// healthy is the state last journaled, not the last observed: a
			// follower that sees a transition while a lease looks valid
			// leaves it unreported, so if that leader died with the cluster
			// the next leader (or a member that sees the lease expire)
			// still journals it. A leadership change can therefore journal
			// one transition twice, never zero times.
			if ready != healthy && everHealthy && (leading || !validLease(snapshot, time.Now())) {
				recordClusterHealth(ctx, cell, member, nats, replicas, ready, snapshot.Epoch)
				healthy = ready
			}
			if !everHealthy || leading {
				healthy = ready
			}
			everHealthy = everHealthy || ready
			viewCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
			if view, err := nats.Observe(viewCtx); err == nil {
				if view.IsMetaLeader && !wasMetaLeader {
					recordMetaLeadership(ctx, cell, member, view, metaLeader, snapshot.Epoch)
				}
				wasMetaLeader = view.IsMetaLeader
				if view.MetaLeader != "" {
					metaLeader = view.MetaLeader
				}
			}
			cancel()
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

// validLease reports that the snapshot observes a live regional lease held by
// some controller.
func validLease(snapshot authority.Snapshot, now time.Time) bool {
	return snapshot.Ready && snapshot.OwnerID != "" && snapshot.Epoch > 0 &&
		(snapshot.ExpiresAt.IsZero() || now.Before(snapshot.ExpiresAt))
}

// recordMetaLeadership journals this server's election as JetStream meta
// leader; previous is the leader it last observed, if any.
func recordMetaLeadership(ctx context.Context, cell, member string, view observability.NATSView, previous string,
	epoch uint64,
) {
	reason := "The JetStream metadata group elected this server."
	if previous != "" && previous != view.ServerName {
		reason = fmt.Sprintf("The JetStream metadata group elected this server; %s led it before.", previous)
	}
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:  cell,
		Actor:   decisionlog.Actor{Slice: "cluster"},
		Kind:    decisionlog.KindLeaderChanged,
		Subject: decisionlog.Subject{Kind: "nats-meta", ID: member, Name: view.ServerName},
		Summary: fmt.Sprintf("%s became the JetStream meta leader", member),
		Reason:  reason,
		Rule:    "JetStream meta leader election",
		Status:  decisionlog.StatusSucceeded,
		Epoch:   epoch,
		Signals: []decisionlog.Signal{{Name: "meta_leader", Text: view.ServerName},
			{Name: "meta_cluster_size", Value: float64(view.MetaClusterSize)}},
	})
}

func recordLeadership(ctx context.Context, cell, member string, snapshot authority.Snapshot, previousEpoch uint64) {
	reason := "This controller acquired the regional authority lease."
	if previousEpoch > 0 && previousEpoch != snapshot.Epoch {
		reason = fmt.Sprintf("This controller acquired the regional authority lease, ending epoch %d.", previousEpoch)
	}
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:  cell,
		Actor:   decisionlog.Actor{Slice: "authority"},
		Kind:    decisionlog.KindLeaderChanged,
		Subject: decisionlog.Subject{Kind: "member", ID: member},
		Summary: fmt.Sprintf("%s became the regional authority leader (epoch %d)", member, snapshot.Epoch),
		Reason:  reason,
		Rule:    "fenced JetStream authority lease",
		Status:  decisionlog.StatusSucceeded,
		Epoch:   snapshot.Epoch,
		Signals: []decisionlog.Signal{{Name: "epoch", Value: float64(snapshot.Epoch)},
			{Name: "lease_expires_at", Text: snapshot.ExpiresAt.UTC().Format(time.RFC3339)}},
	})
}

func recordClusterHealth(ctx context.Context, cell, member string, nats clusterHealth, replicas int,
	healthy bool, epoch uint64,
) {
	signals := []decisionlog.Signal{{Name: "required_replicas", Value: float64(replicas)}}
	viewCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
	if view, err := nats.Observe(viewCtx); err == nil {
		offline := 0
		for _, peer := range view.MetaPeers {
			if peer.Offline {
				offline++
			}
		}
		signals = append(signals,
			decisionlog.Signal{Name: "cluster_peers", Value: float64(view.ClusterPeers), Comparison: ">=",
				Threshold: decisionlog.Threshold(float64(replicas - 1)), Passed: decisionlog.Passed(healthy)},
			decisionlog.Signal{Name: "meta_offline_peers", Value: float64(offline)},
			decisionlog.Signal{Name: "meta_leader", Text: view.MetaLeader})
	}
	cancel()
	decision := decisionlog.Decision{Region: cell, Actor: decisionlog.Actor{Slice: "cluster"},
		Subject: decisionlog.Subject{Kind: "cluster", ID: cell}, Rule: "full regional cluster readiness",
		Epoch: epoch, Signals: signals}
	if healthy {
		decision.Kind, decision.Status = decisionlog.KindQuorumRestored, decisionlog.StatusSucceeded
		decision.Summary = "Regional cluster is back at full strength"
		decision.Reason = fmt.Sprintf("All %d replicas route and the JetStream metadata quorum is current.", replicas)
	} else {
		decision.Kind, decision.Status = decisionlog.KindQuorumDegraded, decisionlog.StatusFailed
		decision.Summary = "Regional cluster dropped below full strength"
		decision.Reason = fmt.Sprintf("%s observed fewer than %d routed replicas or a lagging JetStream metadata quorum.",
			member, replicas)
	}
	decisionlog.Record(ctx, decision)
}

func newHoldJournal(cell string) *holdJournal {
	return &holdJournal{cell: cell, last: map[string]time.Time{}}
}

func (journal *holdJournal) record(ctx context.Context, reason string, now time.Time) {
	journal.mu.Lock()
	if at, seen := journal.last[reason]; seen && now.Sub(at) < holdRepeat {
		journal.mu.Unlock()
		return
	}
	journal.last[reason] = now
	if len(journal.last) > 256 {
		for key, at := range journal.last {
			if now.Sub(at) >= holdRepeat {
				delete(journal.last, key)
			}
		}
	}
	journal.mu.Unlock()
	subject := holdSubject(reason)
	decisionlog.Record(ctx, decisionlog.Decision{
		Region:  journal.cell,
		Actor:   decisionlog.Actor{Slice: "placement"},
		Kind:    decisionlog.KindHeld,
		Subject: subject,
		Summary: "Placement held " + subject.String(),
		Reason:  reason,
		Rule:    "placement reconciliation safety gate",
		Status:  decisionlog.StatusPending,
	})
}

// holdSubject names what a placement hold reason is about.
func holdSubject(reason string) decisionlog.Subject {
	fields := strings.Fields(reason)
	for index := 0; index+1 < len(fields); index++ {
		switch fields[index] {
		case "member":
			return decisionlog.Subject{Kind: "seat", ID: fields[index+1]}
		case "database":
			return decisionlog.Subject{Kind: "database", ID: fields[index+1]}
		case "update":
			return decisionlog.Subject{Kind: "operation", ID: fields[index+1]}
		}
	}
	return decisionlog.Subject{Kind: "placement", ID: "reconciler"}
}

// Holds adapts the placement hold log to the insight engine.
func (log *placementHoldLog) Holds(now time.Time) []insights.Hold {
	var holds []insights.Hold
	seen := map[string]bool{}
	for _, record := range log.recent(now) {
		// Reconciliation errors share the log but are not holds.
		if seen[record.Reason] || strings.HasPrefix(record.Reason, "reconciliation error:") {
			continue
		}
		seen[record.Reason] = true
		holds = append(holds, insights.Hold{Reason: record.Reason, LastSeen: record.At})
	}
	return holds
}

func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

// Attach sets the durable sink and archive. Decisions recorded before a sink
// is attached stay queued (up to the queue bound) and are published once it
// is.
func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and
// the log line are kept.
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

func newConvergenceMemoryRunner() *convergenceMemoryRunner {
	return &convergenceMemoryRunner{
		expectations: make(map[string]*convergenceExpectation),
		violated:     make(chan error, 1),
	}
}

func (r *convergenceMemoryRunner) Recover(context.Context) error { return nil }

func (r *convergenceMemoryRunner) Apply(_ context.Context, workload host.Workload) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	expectation, ok := r.expectations[workload.Digest]
	if !ok || workload.Digest != r.activeDigest || workload.Role != "terrabase" {
		return r.recordViolationLocked(fmt.Errorf("unexpected Apply role=%q digest=%q active=%q", workload.Role, workload.Digest, r.activeDigest))
	}
	if expectation.count != 0 {
		return r.recordViolationLocked(fmt.Errorf("duplicate Apply for digest %s generation %d", workload.Digest, r.activeGen))
	}
	r.observed = host.Observation{
		Role: workload.Role, Digest: workload.Digest, Fingerprint: workload.Fingerprint,
		Running: true, PID: 1,
	}
	completion := convergenceApply{
		Digest: workload.Digest, Fingerprint: workload.Fingerprint,
		Generation: r.activeGen, At: time.Now(),
	}
	expectation.count++
	expectation.completion <- completion
	return nil
}

func (r *convergenceMemoryRunner) Stop(_ context.Context, role string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.observed = host.Observation{Role: role}
	return nil
}

func (r *convergenceMemoryRunner) Observe(_ context.Context, _ string) (host.Observation, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	return r.observed, nil
}

func (*convergenceMemoryRunner) Close(context.Context) error { return nil }

func (r *convergenceMemoryRunner) Expect(digest string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if digest == "" {
		return errors.New("cannot expect an empty artifact digest")
	}
	if _, exists := r.expectations[digest]; exists {
		return fmt.Errorf("artifact digest is not distinct: %s", digest)
	}
	r.expectations[digest] = &convergenceExpectation{completion: make(chan convergenceApply, 1)}
	return nil
}

func (r *convergenceMemoryRunner) Arm(digest string, generation uint64) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.violation != nil {
		return r.violation
	}
	if r.activeDigest != "" {
		previous := r.expectations[r.activeDigest]
		if previous == nil || previous.count != 1 {
			return fmt.Errorf("cannot arm generation %d before prior generation %d completed exactly once", generation, r.activeGen)
		}
	}
	next := r.expectations[digest]
	if next == nil || next.count != 0 {
		return fmt.Errorf("generation %d has missing or previously applied digest %q", generation, digest)
	}
	r.activeDigest, r.activeGen = digest, generation
	return nil
}

func (r *convergenceMemoryRunner) Wait(ctx context.Context, agentDone *convergenceTask, digest string) (convergenceApply, error) {
	r.mu.Lock()
	expectation := r.expectations[digest]
	violation := r.violation
	r.mu.Unlock()
	if violation != nil {
		return convergenceApply{}, violation
	}
	if expectation == nil {
		return convergenceApply{}, fmt.Errorf("no Apply expectation registered for digest %s", digest)
	}
	select {
	case completion := <-expectation.completion:
		return completion, nil
	case err := <-r.violated:
		return convergenceApply{}, err
	case <-agentDone.done:
		return convergenceApply{}, fmt.Errorf("host agent exited before matching Apply: %w", agentDone.result())
	case <-ctx.Done():
		return convergenceApply{}, ctx.Err()
	}
}

func (r *convergenceMemoryRunner) ValidateCounts() error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.violation != nil {
		return r.violation
	}
	for digest, expectation := range r.expectations {
		if expectation.count != 1 {
			return fmt.Errorf("digest %s Apply count=%d, want exactly one", digest, expectation.count)
		}
	}
	return nil
}

func (r *convergenceMemoryRunner) recordViolationLocked(err error) error {
	if r.violation == nil {
		r.violation = err
		select {
		case r.violated <- err:
		default:
		}
	}
	return err
}

func waitForConvergenceHostSession(t *testing.T, ctx context.Context, agentDone *convergenceTask, operatorConfigPath string, output *bytes.Buffer) {
	t.Helper()
	for {
		output.Reset()
		if err := Run(ctx, []string{"operator", "hosts", "--config", operatorConfigPath}, output); err == nil {
			var statuses []host.HostStatus
			if json.Unmarshal(output.Bytes(), &statuses) == nil && len(statuses) == 1 && !statuses[0].SessionExpiresAt.IsZero() {
				return
			}
		}
		select {
		case <-agentDone.done:
			t.Fatalf("host agent exited before session: %v", agentDone.result())
		case <-ctx.Done():
			t.Fatal("host did not establish a session:", ctx.Err())
		case <-time.After(convergencePollInterval):
		}
	}
}

func admitConvergenceArtifacts(t *testing.T, ctx context.Context, root, operatorConfigPath string, source delivery.ArtifactSource, output *bytes.Buffer) []delivery.ArtifactRecord {
	t.Helper()
	artifacts := make([]delivery.ArtifactRecord, 0, convergenceWarmupCount+convergenceSampleCount)
	for index := range convergenceWarmupCount + convergenceSampleCount {
		body := []byte(fmt.Sprintf("#!/bin/sh\n# convergence sample %03d\nsleep 30\n", index+1))
		artifactPath := filepath.Join(root, fmt.Sprintf("guest-%03d", index+1))
		if err := os.WriteFile(artifactPath, body, 0o755); err != nil {
			t.Fatal(err)
		}
		output.Reset()
		if err := Run(ctx, []string{
			"operator", "artifact-push", "--config", operatorConfigPath, "--file", artifactPath,
			"--repository", source.Repository, "--commit", source.Commit, "--tree-digest", source.TreeDigest,
			"--role", "terrabase", "--environment", "test",
		}, output); err != nil {
			t.Fatalf("pre-admit artifact %d: %v", index+1, err)
		}
		var record delivery.ArtifactRecord
		if err := json.Unmarshal(output.Bytes(), &record); err != nil {
			t.Fatalf("decode admitted artifact %d: %v: %s", index+1, err, output.String())
		}
		if record.Digest == "" || record.ManifestDigest == "" || record.Size != int64(len(body)) {
			t.Fatalf("invalid artifact record %d: %+v", index+1, record)
		}
		if index > 0 && slices.ContainsFunc(artifacts, func(previous delivery.ArtifactRecord) bool {
			return previous.Digest == record.Digest
		}) {
			t.Fatalf("artifact %d repeated an existing digest %s", index+1, record.Digest)
		}
		artifacts = append(artifacts, record)
	}
	return artifacts
}

func waitForConvergenceAccepted(t *testing.T, ctx context.Context, agentDone *convergenceTask, operatorConfigPath, operationID, fingerprint string, artifact delivery.ArtifactRecord, generation uint64, output *bytes.Buffer) error {
	t.Helper()
	for {
		output.Reset()
		err := Run(ctx, []string{
			"operator", "status", "--config", operatorConfigPath,
			"--operation-id", operationID, "--fingerprint", fingerprint,
		}, output)
		if err == nil {
			var receipt delivery.Receipt
			if json.Unmarshal(output.Bytes(), &receipt) == nil && receipt.Status == "accepted" {
				if receipt.OperationID != operationID || receipt.Fingerprint != fingerprint ||
					receipt.ArtifactDigest != artifact.Digest || receipt.ManifestDigest != artifact.ManifestDigest ||
					receipt.Generation != generation {
					return fmt.Errorf("accepted receipt does not match desired generation: %+v", receipt)
				}
				return nil
			}
		}
		select {
		case <-agentDone.done:
			return fmt.Errorf("host agent exited before acceptance: %w", agentDone.result())
		case <-ctx.Done():
			return fmt.Errorf("delivery did not reach accepted: %w; output=%s; command error=%v", ctx.Err(), output.String(), err)
		case <-time.After(convergencePollInterval):
		}
	}
}

func collectConvergenceProvenance(t *testing.T) deploymentConvergenceProvenance {
	t.Helper()
	buildInfo, ok := debug.ReadBuildInfo()
	if !ok {
		t.Fatal("Go build information is unavailable")
	}
	revision := convergenceGitOutput(t, "rev-parse", "HEAD")
	tree := convergenceGitOutput(t, "rev-parse", "HEAD^{tree}")
	status := convergenceGitOutput(t, "status", "--porcelain=v1", "--untracked-files=normal")
	dirtyPaths := make([]string, 0)
	for line := range strings.SplitSeq(status, "\n") {
		if strings.TrimSpace(line) != "" {
			if len(line) >= 3 {
				dirtyPaths = append(dirtyPaths, strings.TrimSpace(line[3:]))
			} else {
				dirtyPaths = append(dirtyPaths, line)
			}
		}
	}
	modules := make(map[string]string)
	for _, dependency := range buildInfo.Deps {
		if dependency.Replace != nil {
			modules[dependency.Path] = fmt.Sprintf("%s => %s@%s", dependency.Version, dependency.Replace.Path, dependency.Replace.Version)
		} else {
			modules[dependency.Path] = dependency.Version
		}
	}
	cpuModel := convergenceCPUModel()
	measurementSource, err := os.ReadFile("deployment_convergence_measurement_test.go")
	if err != nil {
		t.Fatalf("read measurement source for provenance: %v", err)
	}
	measurementSourceHash := sha256.Sum256(measurementSource)
	return deploymentConvergenceProvenance{
		Revision: revision, Tree: tree, DirtyPaths: dirtyPaths,
		MeasurementFileSHA256: hex.EncodeToString(measurementSourceHash[:]),
		GoVersion:             buildInfo.GoVersion, RuntimeVersion: runtime.Version(),
		GOOS: runtime.GOOS, GOARCH: runtime.GOARCH, NumCPU: runtime.NumCPU(),
		GOMAXPROCS: runtime.GOMAXPROCS(0), GOMAXPROCSSetting: os.Getenv("GOMAXPROCS"),
		CPUModel: cpuModel, GOTOOLCHAIN: os.Getenv("GOTOOLCHAIN"), Modules: modules,
	}
}

func sameConvergenceSource(first, second deploymentConvergenceProvenance) bool {
	return first.Revision == second.Revision && first.Tree == second.Tree &&
		first.MeasurementFileSHA256 == second.MeasurementFileSHA256 &&
		slices.Equal(first.DirtyPaths, second.DirtyPaths)
}

func convergenceGitOutput(t *testing.T, args ...string) string {
	t.Helper()
	command := exec.Command("git", args...)
	output, err := command.Output()
	if err != nil {
		t.Fatalf("git %s: %v", strings.Join(args, " "), err)
	}
	return strings.TrimSpace(string(output))
}

func convergenceCPUModel() string {
	data, err := os.ReadFile("/proc/cpuinfo")
	if err != nil {
		return ""
	}
	for line := range strings.SplitSeq(string(data), "\n") {
		key, value, found := strings.Cut(line, ":")
		if found && (strings.TrimSpace(key) == "model name" || strings.TrimSpace(key) == "Hardware" || strings.TrimSpace(key) == "Processor") {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

