func (e *edgeReconciler) pass(ctx context.Context) error {
	spec, addresses := e.fence.spec()
	if spec == nil {
		return nil
	}
	epoch, err := e.fence.leading(ctx)
	if err != nil {
		return err
	}
	api, err := e.fence.client(ctx)
	if err != nil {
		return err
	}
	statuses, err := e.fence.hosts.ListHosts(ctx)
	if err != nil {
		return err
	}
	nodeOf := map[string]string{}
	for node, address := range addresses {
		nodeOf[address] = node
	}
	held := map[string]bool{}
	var errs []error
	act := func(f func(context.Context) error) {
		actCtx, cancel := context.WithTimeout(ctx, edgeActTimeout)
		defer cancel()
		errs = append(errs, f(actCtx))
	}
	for _, set := range spec.BackendSets {
		if set.Role == "" {
			continue
		}
		desired, err := e.fence.hosts.ListDesired(ctx, set.Role)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		members := map[string]bool{}
		for _, d := range desired {
			if !d.Withdrawn && addresses[d.Node] != "" {
				members[d.Node] = true
			}
		}
		if len(members) == 0 {
			// Never empty a set on a desired state that reads empty.
			held[set.Name+": no "+set.Role+" replica has a host grant"] = true
			continue
		}
		observed, err := api.ListBackends(ctx, spec.LoadBalancerID, set.Name)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		have := map[string]bool{}
		for _, backend := range observed {
			node, granted := nodeOf[backend.IP]
			switch {
			case !granted || backend.Port != set.Port:
				held[set.Name+": backend "+backend.Name()+" is no node of the cell"] = true
			case !members[node]:
				act(func(ctx context.Context) error {
					reason, err := e.unallocated(ctx, api, epoch, *spec, set, node)
					if reason != "" {
						held[set.Name+": "+reason] = true
					}
					return err
				})
			default:
				have[node] = true
				act(func(ctx context.Context) error {
					return e.member(ctx, api, epoch, *spec, set, node, statuses)
				})
			}
		}
		for _, node := range slices.Sorted(maps.Keys(members)) {
			if !have[node] {
				act(func(ctx context.Context) error { return e.add(ctx, api, epoch, *spec, set, node) })
			}
		}
	}
	if e.ops != nil {
		errs = append(errs, e.instances(ctx, addresses, held))
	}
	e.alert(ctx, epoch, held)
	return errors.Join(errs...)
}

func (e *edgeReconciler) instances(ctx context.Context, addresses map[string]string, held map[string]bool) error {
	api, err := e.ops.instances(ctx)
	if err != nil {
		return err
	}
	instances, err := api.Instances(ctx)
	if err != nil {
		return err
	}
	for _, node := range slices.Sorted(maps.Keys(addresses)) {
		instance, err := findNode(instances, node)
		if err != nil {
			held["instance: "+err.Error()+"; renamed or terminated outside ts-orch"] = true
			continue
		}
		if instance.State == "RUNNING" {
			continue
		}
		if op, found, err := e.ops.load(ctx, node); err != nil {
			return err
		} else if !found || !op.active() {
			held["instance: "+node+" is "+instance.State+" outside a node operation"] = true
		}
	}
	return nil
}

// alert records each newly held condition once, as a held decision, and
// forgets the ones that cleared.
func (e *edgeReconciler) alert(ctx context.Context, epoch uint64, held map[string]bool) {
	e.mu.Lock()
	defer e.mu.Unlock()
	for _, condition := range slices.Sorted(maps.Keys(held)) {
		if e.alerted[condition] {
			continue
		}
		slog.WarnContext(ctx, "edge reconcile leaves a backend to an operator", observability.ComponentKey, "edge", "condition", condition)
		decisionlog.Record(ctx, decisionlog.Decision{Region: e.cell, Actor: decisionlog.Actor{Slice: "edge"},
			Kind: decisionlog.KindHeld, Subject: decisionlog.Subject{Kind: "load-balancer", ID: condition},
			Summary: "Left a load balancer backend for an operator", Reason: "The change is ambiguous: " + condition,
			Status: decisionlog.StatusFailed, Epoch: epoch})
	}
	e.alerted = held
}

func (e *edgeReconciler) member(ctx context.Context, api lb.API, epoch uint64, spec cellspec.ReleaseFence,
	set cellspec.FencedSet, node string, statuses []host.HostStatus,
) error {
	defer e.fence.lockNode(node)()
	record, found, err := e.fence.record(ctx, node)
	if err != nil {
		return err
	}
	backend, exists, err := e.backend(ctx, api, spec, set, node)
	if err != nil || !exists {
		return err
	}
	grace := durationOr(spec.DrainGraceSeconds, defaultFenceGrace)
	if found {
		holders := record.holders()
		pending := slices.ContainsFunc(record.Backends, func(b fencedBackend) bool { return !b.Offline })
		if slices.Contains(holders, holdHealth) {
			if reason, err := nodeRolesServing(ctx, e.fence.hosts, node, time.Time{}); err != nil || reason == "" {
				if err != nil {
					return err
				}
				if returned, err := e.fence.restoreLocked(ctx, api, epoch, node, holdHealth, true); err != nil || !returned {
					return err
				}
				e.corrected(ctx, epoch, node, "Returned a node that serves again")
				return nil
			}
			if pending && slices.Equal(holders, []string{holdHealth}) {
				return e.fence.takeOutRecord(ctx, api, epoch, node, record, grace)
			}
		}
		if pending || !backend.Serving() {
			// A fence or restore in progress owns it, or it is out.
			return nil
		}
		// A hand edit returned a backend its node's holders keep out, or
		// the set joined the fence after the node was taken out.
		index := slices.IndexFunc(record.Backends, func(b fencedBackend) bool {
			return b.LoadBalancerID == spec.LoadBalancerID && b.Set == set.Name && b.IP == backend.IP && b.Port == set.Port
		})
		if index < 0 {
			record.Backends = append(record.Backends, fencedBackend{LoadBalancerID: spec.LoadBalancerID, Set: set.Name,
				IP: backend.IP, Port: set.Port, Weight: 1})
		} else {
			record.Backends[index].Offline = false
		}
		if err := e.fence.save(ctx, epoch, node, record); err != nil {
			return err
		}
		if err := e.fence.takeOutRecord(ctx, api, epoch, node, record, grace); err != nil {
			return err
		}
		e.corrected(ctx, epoch, node, "Took a held node's backend out of rotation again")
		return nil
	}
	weight, backup := backend.Shape()
	switch {
	case !backend.Serving():
		// Out of rotation with no record: a hand edit or a lost record.
		// Held for health, it returns once the node serves.
		record := fenceRecord{Holders: []string{holdHealth}, Backends: []fencedBackend{{LoadBalancerID: spec.LoadBalancerID,
			Set: set.Name, IP: backend.IP, Port: set.Port, Weight: 1, Offline: true}}}
		if err := e.fence.save(ctx, epoch, node, record); err != nil {
			return err
		}
		e.corrected(ctx, epoch, node, "Held an unexplained out-of-rotation backend until its node serves")
		return nil
	case weight > 1 || backup:
		if err := e.fence.update(ctx, api, epoch, fencedBackend{LoadBalancerID: spec.LoadBalancerID, Set: set.Name,
			IP: backend.IP, Port: set.Port, Weight: 1}, false, false); err != nil {
			return err
		}
		e.corrected(ctx, epoch, node, "Made a backup or weighted backend a plain one")
		return nil
	}
	if !e.notServing(node, set.Role, statuses) {
		return nil
	}
	record = fenceRecord{Holders: []string{holdHealth}, Backends: []fencedBackend{{LoadBalancerID: spec.LoadBalancerID,
		Set: set.Name, IP: backend.IP, Port: set.Port, Weight: weight, Backup: backup}}}
	if err := e.fence.save(ctx, epoch, node, record); err != nil {
		return err
	}
	if err := e.fence.takeOutRecord(ctx, api, epoch, node, record, grace); err != nil {
		return err
	}
	e.corrected(ctx, epoch, node, "Took a replica that does not serve out of rotation")
	return nil
}

func (e *edgeReconciler) add(ctx context.Context, api lb.API, epoch uint64, spec cellspec.ReleaseFence,
	set cellspec.FencedSet, node string,
) error {
	defer e.fence.lockNode(node)()
	if _, exists, err := e.backend(ctx, api, spec, set, node); err != nil || exists {
		return err
	}
	_, addresses := e.fence.spec()
	record, found, err := e.fence.record(ctx, node)
	if err != nil {
		return err
	}
	if !found {
		record.Holders = []string{holdHealth}
	} else if !slices.Contains(record.holders(), holdHealth) {
		record.Holders = append(slices.Clone(record.holders()), holdHealth)
		slices.Sort(record.Holders)
	}
	created := fencedBackend{LoadBalancerID: spec.LoadBalancerID, Set: set.Name, IP: addresses[node], Port: set.Port,
		Weight: 1, Offline: true}
	record.Backends = append(slices.DeleteFunc(record.Backends, func(b fencedBackend) bool {
		return b.LoadBalancerID == created.LoadBalancerID && b.Set == created.Set && b.IP == created.IP && b.Port == created.Port
	}), created)
	// Recorded first, so the backend never exists unexplained.
	if err := e.fence.save(ctx, epoch, node, record); err != nil {
		return err
	}
	if err := e.fence.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	request, err := api.CreateBackend(ctx, spec.LoadBalancerID, set.Name,
		lb.Backend{IP: created.IP, Port: created.Port}.Fenced(true, true))
	if err != nil {
		return err
	}
	if err := api.WaitWorkRequest(ctx, request); err != nil {
		return err
	}
	e.corrected(ctx, epoch, node, fmt.Sprintf("Added %s's backend to %s out of rotation", node, set.Name))
	return nil
}

func (e *edgeReconciler) unallocated(ctx context.Context, api lb.API, epoch uint64, spec cellspec.ReleaseFence,
	set cellspec.FencedSet, node string,
) (string, error) {
	defer e.fence.lockNode(node)()
	backend, exists, err := e.backend(ctx, api, spec, set, node)
	if err != nil || !exists {
		return "", err
	}
	if backend.Serving() {
		unhealthy, err := api.UnhealthyBackends(ctx, spec.LoadBalancerID, set.Name)
		if err != nil {
			return "", err
		}
		if !unhealthy[backend.Name()] {
			return fmt.Sprintf("%s serves without a %s replica", node, set.Role), nil
		}
	}
	if err := e.fence.fencer.Guard(ctx, epoch); err != nil {
		return "", err
	}
	request, err := api.DeleteBackend(ctx, spec.LoadBalancerID, set.Name, backend.Name())
	if err != nil {
		return "", err
	}
	if err := api.WaitWorkRequest(ctx, request); err != nil {
		return "", err
	}
	if record, found, err := e.fence.record(ctx, node); err != nil {
		return "", err
	} else if found {
		record.Backends = slices.DeleteFunc(record.Backends, func(b fencedBackend) bool {
			return b.LoadBalancerID == spec.LoadBalancerID && b.Set == set.Name && b.IP == backend.IP && b.Port == set.Port
		})
		if err := e.fence.save(ctx, epoch, node, record); err != nil {
			return "", err
		}
	}
	e.corrected(ctx, epoch, node, fmt.Sprintf("Removed %s's backend from %s: it has no %s replica", node, set.Name, set.Role))
	return "", nil
}

func (f *releaseFence) record(ctx context.Context, node string) (fenceRecord, bool, error) {
	entry, err := f.kv.Get(ctx, fencedKey(node))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return fenceRecord{}, false, nil
	}
	if err != nil {
		return fenceRecord{}, false, err
	}
	var record fenceRecord
	if err := json.Unmarshal(entry.Value(), &record); err != nil {
		return fenceRecord{}, false, fmt.Errorf("decode the fence of %s: %w", node, err)
	}
	return record, true, nil
}

func (f *releaseFence) save(ctx context.Context, epoch uint64, node string, record fenceRecord) error {
	wire, err := json.Marshal(record)
	if err != nil {
		return err
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return err
	}
	_, err = f.kv.Put(ctx, fencedKey(node), wire)
	return err
}

// restore lets holder go of node's fence. When no other holder keeps the
// node out, it returns the recorded backends to rotation on the load
// balancer they were taken from and, with healthy, waits until their
// health checks pass; it reports whether any were returned.
func (f *releaseFence) restore(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool) (bool, error) {
	unlock, err := f.lockNodeContext(ctx, node)
	if err != nil {
		return false, err
	}
	defer unlock()
	return f.restoreLocked(ctx, api, epoch, node, holder, healthy)
}

// restoreLocked is restore with node's lock held.
func (f *releaseFence) restoreLocked(ctx context.Context, api lb.API, epoch uint64, node, holder string, healthy bool,
) (bool, error) {
	record, found, err := f.record(ctx, node)
	if err != nil || !found {
		return false, err
	}
	if others := slices.DeleteFunc(slices.Clone(record.holders()), func(h string) bool { return h == holder }); len(others) > 0 {
		if len(others) == len(record.holders()) {
			return false, nil
		}
		record.Holders = others
		return false, f.save(ctx, epoch, node, record)
	}
	// Recorded as back in rotation before the load balancer changes, so a
	// restore cut short leaves a record the next fence drains again; the
	// holder stays on it until it is gone, so the holder finishes it.
	record.Holders = []string{holder}
	for i := range record.Backends {
		record.Backends[i].Offline = false
	}
	if err := f.save(ctx, epoch, node, record); err != nil {
		return false, err
	}
	for _, backend := range record.Backends {
		if err := f.update(ctx, api, epoch, backend, false, false); err != nil {
			return false, err
		}
	}
	for _, backend := range record.Backends {
		name := lb.Backend{IP: backend.IP, Port: backend.Port}.Name()
		for healthy {
			unhealthy, err := api.UnhealthyBackends(ctx, backend.LoadBalancerID, backend.Set)
			if err != nil {
				return false, err
			}
			if !unhealthy[name] {
				break
			}
			if err := f.wait(ctx, epoch, fencePoll); err != nil {
				return false, fmt.Errorf("%s backend %s did not pass its health check: %w", backend.Set, name, err)
			}
		}
	}
	if err := f.fencer.Guard(ctx, epoch); err != nil {
		return false, err
	}
	slog.InfoContext(ctx, "release fence returned a node to rotation", observability.ComponentKey, "rollout", "node", node)
	return len(record.Backends) > 0, f.kv.Delete(ctx, fencedKey(node))
}

func testRolloutJetStream(t *testing.T) jetstream.JetStream {
	t.Helper()
	auth := newAuthenticatedNATS(t, "gru")
	runtime, err := auth.start(t, t.Context(), natscell.Config{Cell: "gru", Embedded: &natscell.Embedded{}})
	if err != nil {
		t.Fatal(err)
	}
	return runtime.JetStream()
}

func (a *authenticatedNATS) start(t *testing.T, ctx context.Context, cfg natscell.Config) (*natscell.Runtime, error) {
	t.Helper()
	runtime, err := natscell.Start(ctx, a.config(t, cfg))
	if err != nil {
		return nil, err
	}
	t.Cleanup(func() { _ = runtime.Close() })
	if cfg.Embedded != nil {
		if err := runtime.ApplyCellClaim(ctx, 1, a.cellJWT); err != nil {
			return nil, fmt.Errorf("apply fixture claim: %w", err)
		}
		if err := runtime.Bridge().OpenUntil(1, a.cellJWT, time.Now().Add(5*time.Minute)); err != nil {
			return nil, fmt.Errorf("open fixture bridge: %w", err)
		}
	}
	return runtime, nil
}

type channelBucket struct {
	mu      sync.Mutex
	objects map[string][]byte
	etags   map[string]string
	version int
	puts    map[string]int
}

func newChannelBucket() *channelBucket {
	return &channelBucket{objects: map[string][]byte{}, etags: map[string]string{}, puts: map[string]int{}}
}

type objectStatus int

func (err objectStatus) Error() string          { return fmt.Sprintf("HTTP %d", int(err)) }
func (err objectStatus) GetHTTPStatusCode() int { return int(err) }
func (objectStatus) GetMessage() string         { return "" }
func (objectStatus) GetCode() string            { return "" }
func (objectStatus) GetOpcRequestID() string    { return "" }

func (b *channelBucket) GetObject(_ context.Context, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	data, ok := b.objects[*request.ObjectName]
	if !ok {
		return objectstorage.GetObjectResponse{}, objectStatus(404)
	}
	etag := b.etags[*request.ObjectName]
	return objectstorage.GetObjectResponse{Content: io.NopCloser(bytes.NewReader(data)), ETag: &etag}, nil
}

func (b *channelBucket) PutObject(_ context.Context, request objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error) {
	data, err := io.ReadAll(request.PutObjectBody)
	if err != nil {
		return objectstorage.PutObjectResponse{}, err
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	name := *request.ObjectName
	etag, exists := b.etags[name]
	if request.IfNoneMatch != nil && exists || request.IfMatch != nil && *request.IfMatch != etag {
		return objectstorage.PutObjectResponse{}, objectStatus(412)
	}
	b.version++
	b.objects[name], b.etags[name] = data, fmt.Sprintf("etag-%d", b.version)
	b.puts[name]++
	return objectstorage.PutObjectResponse{}, nil
}

func newFunctionPublicationSigner(t *testing.T) functionPublicationSigner {
	t.Helper()
	module, err := hex.DecodeString("0061736d0100000001040160000003020100070a01065f737461727400000a040102000b")
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI,
		TenantID: entityid.Derive("tenant", "function-controller"), FunctionID: "echo", Revision: "first",
		Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: "canary", Cell: "GRU", Sequence: 42}
	root, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	publicKey, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion,
		SubjectKeyID: keyID, SubjectPublicKey: publicKey,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}},
	}, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
	if err != nil {
