func (source functionIntentSource) CurrentFunction(ctx context.Context, tenant, function string) (release.VerifiedFunction, error) {
	if source.authority == nil || source.js == nil || source.roots == nil || source.roots.reply("").Head != source.rootHead {
		return release.VerifiedFunction{}, errors.New("function roots changed during current intent observation")
	}
	if err := source.authority.Guard(ctx, source.epoch); err != nil {
		return release.VerifiedFunction{}, err
	}
	proof, err := source.reader.CurrentFunction(ctx, tenant, function)
	if err != nil {
		return release.VerifiedFunction{}, err
	}
	ctx, cancel := context.WithDeadline(ctx, proof.ExpiresAt())
	defer cancel()
	if err := source.authority.Guard(ctx, source.epoch); err != nil {
		return release.VerifiedFunction{}, err
	}
	if err := rootTrustHeadCurrent(ctx, source.js, source.roots, source.rootHead); err != nil {
		return release.VerifiedFunction{}, err
	}
	state := source.authority.Current()
	if !state.CanMutate() || state.Epoch != source.epoch {
		return release.VerifiedFunction{}, authority.ErrFenced
	}
	if source.roots.reply("").Head != source.rootHead || !proof.Valid() {
		return release.VerifiedFunction{}, errors.New("function authority changed during current intent observation")
	}
	if err := ctx.Err(); err != nil {
		return release.VerifiedFunction{}, err
	}
	return proof, nil
}

func (controller functionController) ingest(ctx context.Context, epoch uint64) error {
	location, err := controller.config.Channel.get(ctx)
	if err != nil {
		return err
	}
	channel, found, err := releasechannel.ReadFunctionChannel(ctx, location)
	if err != nil || !found {
		return err
	}
	var failures []error
	for _, entry := range channel.Entries {
		if err := controller.ingestRelease(ctx, epoch, location, entry); err != nil {
			failures = append(failures, err)
		}
	}
	return errors.Join(failures...)
}

func (controller functionController) ingestRelease(ctx context.Context, epoch uint64, location releasechannel.Location, entry releasechannel.FunctionRelease) error {
	if controller.config.Roots == nil {
		return errors.New("function publication requires current regional roots")
	}
	rootHead := controller.config.Roots.reply("").Head
	claim, err := entry.Claim()
	if err != nil {
		return err
	}
	if claim.Cell != strings.ToUpper(controller.config.Cell) || claim.Environment != controller.config.Environment {
		return release.ErrExpectationMismatch
	}
	minimum, expected := uint64(1), uint64(0)
	var previous authority.FunctionIntent
	current, err := controller.config.Authority.ReadFunctionIntent(ctx, claim.TenantID, claim.FunctionID)
	if err == nil {
		previous, err = authority.DecodeFunctionIntent(current)
		if err != nil {
			return err
		}
		minimum, expected = previous.Claim.Sequence, current.Sequence
	} else if !errors.Is(err, authority.ErrNotFound) {
		return err
	}
	module, err := releasechannel.ReadFunctionModule(ctx, location, claim.Digest)
	if err != nil {
		return err
	}
	proof, err := release.VerifyFunctionCurrent(entry.Envelope, entry.Delegation, module, controller.config.Material.Reader.Roots(), release.FunctionExpectation{
		Environment: controller.config.Environment, Cell: strings.ToUpper(controller.config.Cell), TenantID: claim.TenantID,
		FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: minimum,
	}, time.Now())
	if err != nil {
		return err
	}
	if previous.EnvelopeSHA256 == proof.EnvelopeSHA256() {
		if !bytes.Equal(previous.Delegation, proof.Delegation()) {
			return authority.ErrConflict
		}
		return nil
	}
	if err := controller.config.Authority.Guard(ctx, epoch); err != nil {
		return err
	}
	// Publishing metadata before the intent invalidates stale garbage collection snapshots.
	stored, err := controller.config.Material.Reader.Artifacts.Put(ctx, jetstream.ObjectMeta{Name: "sha256-" + proof.Claim().Digest}, bytes.NewReader(proof.Module()))
	if err != nil {
		return err
	}
	if stored == nil || stored.Size != uint64(proof.Claim().Bytes) || stored.Opts != nil && stored.Opts.Link != nil {
		return errors.New("function artifact readback differs from verified module")
	}
	// Root adoption and its leader's KV writes wait until this intent CAS completes.
	controller.config.Roots.adopting.Lock()
	defer controller.config.Roots.adopting.Unlock()
	if controller.config.Roots.reply("").Head != rootHead {
		return errors.New("function roots changed during artifact publication")
	}
	proof, err = release.VerifyFunctionCurrent(entry.Envelope, entry.Delegation, module, controller.config.Roots.current(), release.FunctionExpectation{
		Environment: controller.config.Environment, Cell: strings.ToUpper(controller.config.Cell), TenantID: claim.TenantID,
		FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: minimum,
	}, time.Now())
	if err != nil {
		return err
	}
	_, err = controller.config.Authority.CommitFunctionIntent(ctx, epoch, entityid.Derive("function-publication", proof.EnvelopeSHA256()), expected, proof)
	return err
}

func functionDemandSource(config functionControllerConfig) func(context.Context) ([]nodescale.CapacityDemand, error) {
	return func(ctx context.Context) ([]nodescale.CapacityDemand, error) {
		if config.Authority == nil || config.JS == nil || config.Client == nil || config.Roots == nil || config.Factory == nil || config.Worker == nil || config.Evidence == nil || config.Material.Reader.Roots == nil ||
			!release.ValidRegion(strings.ToUpper(config.Cell)) || !release.ValidEnvironment(config.Environment) {
			return nil, errors.New("function capacity requires current authority, manager and qualified worker source")
		}
		epoch := config.Authority.Current().Epoch
		if err := config.Authority.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		entries, err := config.Authority.ListFunctionIntents(ctx)
		if err != nil {
			return nil, err
		}
		reader := config.Material.Reader
		reader.Authority = config.Authority
		current := functionIntentSource{reader: reader, js: config.JS, authority: config.Authority, epoch: epoch, roots: config.Roots, rootHead: config.Roots.reply("").Head}
		slots := map[string]uint64{}
		for _, entry := range entries {
			stored, err := authority.DecodeFunctionIntent(entry)
			if err != nil {
				return nil, err
			}
			proof, err := current.CurrentFunction(ctx, stored.Claim.TenantID, stored.Claim.FunctionID)
			if err != nil {
				return nil, err
			}
			claim := proof.Claim()
			if claim.Cell != strings.ToUpper(config.Cell) || claim.Environment != config.Environment {
				return nil, release.ErrExpectationMismatch
			}
			worker, err := config.Worker(ctx, proof)
			if err != nil {
				return nil, err
			}
			target := release.ContainerTarget{
				Cell: claim.Cell, Environment: claim.Environment, Role: swarmruntime.FunctionWorkerRole, Architecture: worker.Architecture,
			}
			allocations, err := currentContainerAllocations(ctx, config.Factory, worker.Bundle, reader.Roots(), target)
			if err != nil {
				return nil, err
			}
			verified, err := release.VerifyContainerCurrent(ctx, worker.Bundle, reader.Roots(), target, time.Now(), proof.ExpiresAt(), config.Evidence, allocations)
			if err != nil {
				return nil, err
			}
			demand, err := functionServiceTarget(proof, worker.Architecture).PendingCapacity(ctx, config.Client, current, verified)
			if err != nil {
				return nil, err
			}
			if demand.Architecture != worker.Architecture || math.MaxUint64-slots[demand.Architecture] < demand.Slots {
				return nil, errors.New("function capacity architecture or slot count differs from qualified worker")
			}
			slots[demand.Architecture] += demand.Slots
		}
		architectures := slices.Sorted(maps.Keys(slots))
		demands := make([]nodescale.CapacityDemand, 0, len(architectures))
		for _, architecture := range architectures {
			demands = append(demands, nodescale.CapacityDemand{Architecture: architecture, Slots: slots[architecture]})
		}
		if err := config.Authority.Guard(ctx, epoch); err != nil {
			return nil, err
		}
		if config.Roots.reply("").Head != current.rootHead {
			return nil, errors.New("function roots changed during capacity observation")
		}
		return demands, ctx.Err()
	}
}

func currentContainerAllocations(ctx context.Context, factory *ociclient.Factory, bundle release.ContainerBundle, roots trust.Keyring, target release.ContainerTarget) (release.SequenceLocation, error) {
	if ctx == nil || factory == nil {
		return release.SequenceLocation{}, errors.New("container allocation requires context and OCI credentials")
	}
	if err := ctx.Err(); err != nil {
		return release.SequenceLocation{}, err
	}
	envelope, err := trust.DecodeEnvelope(bundle.Migration)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	// Established migrations retain authority after their submission envelope expires.
	migration, err := release.VerifySequenceMigrationHistorical(envelope, roots, target.Role, target.Environment)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	entry, ok := catalog.Lookup(migration.Region)
	if !ok {
		return release.SequenceLocation{}, errors.New("container allocation migration has no OCI region")
	}
	regional, err := factory.ForRegion(entry.OCIRegion)
	if err != nil {
		return release.SequenceLocation{}, err
	}
	client, err := regional.ObjectStorage()
	if err != nil {
		return release.SequenceLocation{}, err
	}
	return release.SequenceLocation{Client: containerAllocationReader{client: client}, Namespace: migration.Namespace, Bucket: migration.Bucket}, nil
}

