func (i FunctionServiceIntent) PendingCapacity(ctx context.Context, client api.ControlClient, current CurrentFunctionIntent, worker release.VerifiedContainer) (FunctionCapacityDemand, error) {
	if current == nil {
		return FunctionCapacityDemand{}, errors.New("function capacity requires current signed intent authority")
	}
	function, err := current.CurrentFunction(ctx, i.TenantID, i.FunctionID)
	if err != nil {
		return FunctionCapacityDemand{}, err
	}
	spec, err := i.serviceSpec(function, worker)
	if err != nil {
		return FunctionCapacityDemand{}, err
	}
	if err := i.VerifyWorkerFloor(ctx, client, worker); err != nil {
		return FunctionCapacityDemand{}, err
	}
	listed, err := client.ListServices(ctx, &api.ListServicesRequest{Filters: &api.ListServicesRequest_Filters{Names: []string{spec.Annotations.Name}}})
	if err != nil {
		return FunctionCapacityDemand{}, err
	}
	if listed == nil || len(listed.Services) > 1 {
		return FunctionCapacityDemand{}, errors.New("function capacity requires an unambiguous service identity")
	}
	demand := FunctionCapacityDemand{Architecture: i.Architecture}
	if len(listed.Services) == 1 {
		service := listed.Services[0]
		if service == nil || service.PendingDelete || !proto.Equal(&service.Spec, spec) {
			return FunctionCapacityDemand{}, errors.New("function capacity service differs from current qualified intent")
		}
		tasks, err := client.ListTasks(ctx, &api.ListTasksRequest{Filters: &api.ListTasksRequest_Filters{ServiceIDs: []string{service.ID}, DesiredStates: []api.TaskState{api.TaskStateRunning}}})
		if err != nil {
			return FunctionCapacityDemand{}, err
		}
		if tasks == nil {
			return FunctionCapacityDemand{}, errors.New("function capacity task observation is unavailable")
		}
		for _, task := range tasks.Tasks {
			if task == nil || task.DesiredState != api.TaskStateRunning || task.NodeID != "" || task.Status.State >= api.TaskStateAssigned {
				continue
			}
			if err := i.VerifyTask(task, service, function, worker); err != nil {
				return FunctionCapacityDemand{}, err
			}
			demand.Slots++
		}
	}
	latest, err := current.CurrentFunction(ctx, i.TenantID, i.FunctionID)
	if err != nil {
		return FunctionCapacityDemand{}, err
	}
	if !latest.Valid() || latest.EnvelopeSHA256() != function.EnvelopeSHA256() {
		return FunctionCapacityDemand{}, errors.New("function intent changed during capacity observation")
	}
	if err := i.VerifyWorkerFloor(ctx, client, worker); err != nil {
		return FunctionCapacityDemand{}, err
	}
	return demand, ctx.Err()
}

func (controller functionController) requireUnusedMaterial(ctx context.Context, binding functionmaterial.Binding) error {
	epoch := controller.config.Authority.Current().Epoch
	if err := controller.config.Authority.Guard(ctx, epoch); err != nil {
		return err
	}
	response, err := controller.config.Client.GetTask(ctx, &api.GetTaskRequest{TaskID: binding.TaskID})
	if status.Code(err) == codes.NotFound {
		return controller.config.Authority.Guard(ctx, epoch)
	}
	if err != nil {
		return err
	}
	if response == nil || response.Task == nil {
		return errors.New("function material retirement requires an authoritative task observation")
	}
	task := response.Task
	if task.ID != binding.TaskID || task.ServiceID != binding.ServiceID || task.NodeID != binding.NodeID {
		return errors.New("function material retirement task differs from its immutable recipient")
	}
	// Desired shutdown alone does not prove that the assigned process stopped.
	switch task.Status.State {
	case api.TaskStateCompleted, api.TaskStateShutdown, api.TaskStateFailed, api.TaskStateRejected, api.TaskStateRemove, api.TaskStateOrphaned:
		return controller.config.Authority.Guard(ctx, epoch)
	default:
		return errors.New("function material remains referenced by an assigned task")
	}
}

func Start(ctx context.Context, js jetstream.JetStream, config Config) (*Runtime, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	config = config.withDefaults()
	if err := config.validate(); err != nil {
		return nil, err
	}
	if config.ClockCheck != nil && config.ClockCheck() != nil {
		return nil, ErrClockUnhealthy
	}
	logger := config.Logger
	if logger == nil {
		logger = slog.Default()
	}
	stream, err := openControlStream(ctx, js, config.Replicas)
	if err != nil {
		return nil, fmt.Errorf("open authority control log: %w", err)
	}
	readCtx, readCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readStream, err := js.Stream(readCtx, ControlStreamName)
	readCancel()
	if err != nil {
		return nil, fmt.Errorf("open authority read handle: %w", err)
	}
	infoCtx, infoCancel := context.WithTimeout(ctx, authorityAPITimeout)
	readInfo, err := readStream.Info(infoCtx)
	infoCancel()
	if err != nil {
		return nil, fmt.Errorf("inspect authority read handle: %w", err)
	}
	if err := verifyControlStreamConfig(readInfo.Config, config.Replicas); err != nil {
		return nil, fmt.Errorf("validate authority read handle: %w", err)
	}
	loopCtx, cancel := context.WithCancel(ctx)
	runtime := &Runtime{
		js:          js,
		publisher:   js,
		stream:      stream,
		readStream:  readStream,
		config:      config,
		leaseSub:    fmt.Sprintf("%s.%s.lease", controlSubjectRoot, config.Scope),
		ownerID:     entityid.New(),
		logger:      logger,
		diagnostics: authorityDiagnosticQueue,
		diagTimes:   make(map[string]time.Time),
		cancel:      cancel,
		done:        make(chan struct{}),
	}
	runtime.publishSnapshot(Snapshot{Scope: config.Scope, DeploymentID: config.DeploymentID, CandidateID: config.CandidateID, OwnerID: runtime.ownerID, Reason: "not-observed"})
	runtime.logSnapshotTransition()
	var observeErr error
	for attempt := range startupReconcileAttempts {
		observeErr = runtime.reconcileWithRetry(loopCtx)
		runtime.logSnapshotTransition()
		if observeErr != nil && loopCtx.Err() != nil {
			observeErr = loopCtx.Err()
			break
		}
		if observeErr == nil || !retryableStartupReconcileError(loopCtx, observeErr) || attempt+1 == startupReconcileAttempts {
			break
		}
		timer := time.NewTimer(startupReconcileDelay(attempt, observeErr))
		select {
		case <-loopCtx.Done():
			observeErr = loopCtx.Err()
			timer.Stop()
		case <-timer.C:
		}
	}
	if observeErr != nil {
		cancel()
		close(runtime.done)
		return nil, fmt.Errorf("observe authority lease: %w", observeErr)
	}
	go runtime.run(loopCtx)
	return runtime, nil
}

